"// Only hide when the command is exactly `/review tests` (should_run) AND the
// commenter is an authorized collaborator (write/maintain/admin). This mirrors
// the workflow's own role gate but is self-contained, so an unauthorized user's
// comment is always left visible. A failed hide must not block activation.
// Only act on newly-created comments. The gh-aw slash_command trigger also fires
// on `edited`, so without this guard, editing any existing comment to say
// `/review tests` would minimize that comment (and collapse its entire history).
if (context.payload.action !== 'created') {
  core.info('Skipping hide: comment was edited, not created.');
  return;
}
const { owner, repo } = context.repo;
const actor = context.actor;
let permission = 'none';
try {
  const res = await github.rest.repos.getCollaboratorPermissionLevel({ owner, repo, username: actor });
  permission = res.data.permission;
} catch (e) {
  core.info(`Permission lookup for ${actor} failed: ${e.message}`);
}
// Must mirror the workflow `roles:` frontmatter (admin/maintain/write) — keep in sync.
if (!['admin', 'maintain', 'write'].includes(permission)) {
  core.info(`Actor ${actor} is not an authorized collaborator (${permission}); leaving the /review tests comment.`);
  return;
}
// Minimize (hide as resolved) rather than delete: the rerun scanner replays the PR's
// REST comment history, and minimized comments are still returned by the REST list
// endpoint — only collapsed in the web UI. node_id is the comment's GraphQL global id.
const subjectId = context.payload.comment.node_id;
try {
  await github.graphql(
    `mutation($id: ID!) {
       minimizeComment(input: { subjectId: $id, classifier: RESOLVED }) {
         minimizedComment { isMinimized }
       }
     }`,
    { id: subjectId }
  );
  core.info(`Hid /review tests command comment ${subjectId} as resolved.`);
} catch (e) {
  core.warning(`Could not hide /review tests command comment ${subjectId}: ${e.message}`);
}
"; "try {
  await github.rest.issues.removeLabel({
    ...context.repo,
    issue_number: context.payload.pull_request.number,
    name: 'architecture-review-needed'
  });
} catch (e) {
  core.warning(`Could not remove label: ${e.message}`);
}
"; "const pr = context.payload.pull_request.number;
// Remove trigger label
try {
  await github.rest.issues.removeLabel({
    ...context.repo,
    issue_number: pr,
    name: 'architecture-review-needed'
  });
} catch (e) {
  core.warning(`Could not remove trigger label: ${e.message}`);
}
// Add in-progress label
try {
  await github.rest.issues.addLabels({
    ...context.repo,
    issue_number: pr,
    labels: ['architecture-review-in-progress']
  });
} catch (e) {
  core.warning(`Could not add in-progress label: ${e.message}`);
}
"

[{'name': 'Post mention comment', 'uses': 'actions/github-script@v8', 'with': {'script': "const fs = require('fs');
const outputFile = process.env.GH_AW_AGENT_OUTPUT;
const issueNumber = context.issue.number;
const owner = context.repo.owner;
const repo = context.repo.repo;

async function failSafe(reason) {
  core.error(`mention_owners failed: ${reason}`);
  try {
    await github.rest.issues.addLabels({
      owner, repo, issue_number: issueNumber,
      labels: ['needs-team-triage']
    });
    await github.rest.issues.createComment({
      owner, repo, issue_number: issueNumber,
      body: '⚠️ Automated triage was unable to complete owner notification for this issue. Routing for manual triage'
    });
  } catch (recoveryError) {
    core.error(`Recovery also failed: ${recoveryError.message}`);
  }
  core.setFailed(reason);
}

if (!outputFile) {
  await failSafe('No agent output path provided');
  return;
}
if (!fs.existsSync(outputFile)) {
  await failSafe(`Agent output file not found: ${outputFile}`);
  return;
}

let agentOutput;
try {
  agentOutput = JSON.parse(fs.readFileSync(outputFile, 'utf8'));
} catch (parseError) {
  await failSafe(`Failed to parse agent output: ${parseError.message}`);
  return;
}

if (!agentOutput || !Array.isArray(agentOutput.items)) {
  await failSafe('Agent output missing items array');
  return;
}

const items = agentOutput.items.filter(i => i.type === 'mention_owners');
if (items.length === 0) {
  await failSafe('No mention_owners items in agent output');
  return;
}

for (const item of items) {
  try {
    await github.rest.issues.createComment({
      owner, repo, issue_number: issueNumber,
      body: item.message
    });
    core.info(`Posted routing comment on #${issueNumber}`);
  } catch (apiError) {
    await failSafe(`GitHub API error posting comment: ${apiError.message}`);
    return;
  }
}
"}}]; [{'name': 'Post mention comment', 'uses': 'actions/github-script@v8', 'with': {'script': "const fs = require('fs');
const outputFile = process.env.GH_AW_AGENT_OUTPUT;
const issueNumber = context.issue.number;
const owner = context.repo.owner;
const repo = context.repo.repo;

async function failSafe(reason) {
  core.error(`mention_owners failed: ${reason}`);
  try {
    await github.rest.issues.addLabels({
      owner, repo, issue_number: issueNumber,
      labels: ['needs-team-triage']
    });
    await github.rest.issues.createComment({
      owner, repo, issue_number: issueNumber,
      body: '⚠️ Automated triage was unable to complete owner notification for this issue. Routing for manual triage'
    });
  } catch (recoveryError) {
    core.error(`Recovery also failed: ${recoveryError.message}`);
  }
  core.setFailed(reason);
}

if (!outputFile) {
  await failSafe('No agent output path provided');
  return;
}
if (!fs.existsSync(outputFile)) {
  await failSafe(`Agent output file not found: ${outputFile}`);
  return;
}

let agentOutput;
try {
  agentOutput = JSON.parse(fs.readFileSync(outputFile, 'utf8'));
} catch (parseError) {
  await failSafe(`Failed to parse agent output: ${parseError.message}`);
  return;
}

if (!agentOutput || !Array.isArray(agentOutput.items)) {
  await failSafe('Agent output missing items array');
  return;
}

const items = agentOutput.items.filter(i => i.type === 'mention_owners');
if (items.length === 0) {
  await failSafe('No mention_owners items in agent output');
  return;
}

for (const item of items) {
  if (!item.owners || typeof item.owners !== 'string' || !item.owners.trim()) {
    await failSafe('mention_owners item missing owners field');
    return;
  }

  const mentions = item.owners
    .split(/[\s,]+/)
    .map(s => s.trim())
    .filter(Boolean)
    .map(raw => {
      const normalized = raw.replace(/^\\?@/, '');
      if (/\r|\n/.test(normalized)) return null;
      if (!/^[A-Za-z0-9-]+(?:\/[A-Za-z0-9-]+)?$/.test(normalized)) return null;
      return `@${normalized}`;
    })
    .filter(Boolean);

  if (mentions.length === 0) {
    await failSafe('No valid owners after parsing owners field');
    return;
  }

  const body = item.message
    ? `${item.message} ${mentions.join(' ')}`
    : mentions.join(' ');

  try {
    await github.rest.issues.createComment({
      owner, repo, issue_number: issueNumber,
      body
    });
    core.info(`Posted routing comment on #${issueNumber} mentioning: ${mentions.join(', ')}`);
  } catch (apiError) {
    await failSafe(`GitHub API error posting comment: ${apiError.message}`);
    return;
  }
}
