.github/scripts/Invoke-RerunReviewTrigger.ps1 @scriptArgs
"}]; [{'name': 'Checkout repository scripts', 'uses': 'actions/checkout@v4', 'with': {'persist-credentials': False}}, {'name': 'Download rerun candidate context', 'uses': 'actions/download-artifact@v8.0.1', 'with': {'name': 'rerun-candidates', 'path': '${{ runner.temp }}/rerun-candidates'}}, {'name': 'Validate rerun scanner decisions', 'shell': 'pwsh', 'env': {'RERUN_CANDIDATES_PATH': '${{ runner.temp }}/rerun-candidates/candidates.json'}, 'run': ".github/scripts/Invoke-RerunReviewTrigger.ps1 -DefaultPipelineRef 'main'
"}, {'name': 'Dispatch review-trigger.yml for validated decisions', 'if': '${{ !cancelled() }}', 'uses': 'actions/github-script@v8', 'with': {'github-token': '${{ secrets.GITHUB_TOKEN }}', 'script': "const fs = require('fs');
const readyLabel = 's/agent-ready-for-rerun';
const dryRun = process.env.DRY_RUN === 'true';
const actionsPath = process.env.RERUN_ACTIONS_PATH;
const { owner, repo } = context.repo;

if (!actionsPath || !fs.existsSync(actionsPath)) {
  core.info('No rerun actions file found; nothing to dispatch.');
  return;
}

let actions;
try {
  actions = JSON.parse(fs.readFileSync(actionsPath, 'utf8') || '[]');
} catch (e) {
  core.setFailed(`Failed to parse rerun actions file: ${e.message}`);
  return;
}
if (!Array.isArray(actions)) { actions = actions ? [actions] : []; }

let hadFailure = false;

async function react(commentId, content) {
  if (!commentId || commentId <= 0) { return; }
